import hashlib, json, requests

API_KEY = "your_api_key"
# 平台底层维护了多个上游账号，为了保证亲和性 cache_task_id 参数配置能保证 cache 缓存命中率, 具体参数解释 https://iwiki.woa.com/p/4051772719 务必替换成cache_task_id=<32位MD5>
CACHE_TASK_ID = hashlib.md5(f"task_demo:{API_KEY}".encode()).hexdigest()
PROVIDER = "google-vertex"
URL = (
    "http://api.aihub.woa.com/v1/publishers/anthropic/"
    "models/claude-opus-5-5:streamRawPredict"
)
HEADERS = {
    "Content-Type": "application/json",
    "Authorization": (
        f"Bearer {API_KEY}?provider={PROVIDER}"
        f"&cache_task_id={CACHE_TASK_ID}"
    ),
}

body = {
    "anthropic_version": "vertex-2023-10-16",
    "max_tokens": 4096,
    "thinking": {"type": "adaptive"},
    "output_config": {"effort": "medium"},
    "stream": True,
    "messages": [
        {"role": "user", "content": "用一句话解释什么是分布式锁"},
    ],
}

r = requests.post(
    URL, headers=HEADERS, json=body, timeout=120, stream=True
)
r.raise_for_status()
for line in r.iter_lines(decode_unicode=True):
    if not line or not line.startswith("data:"):
        continue
    event = json.loads(line[5:].lstrip())
    if event.get("type") == "content_block_delta":
        delta = event.get("delta", {})
        if delta.get("type") == "text_delta":
            print(delta.get("text", ""), end="", flush=True)
print()
